	std::string prefix = to_lower(prefix_);
	auto& tests = get_tests();

	// count the number of tests to run:
	uint32_t to_run = 0;
	for (auto& test : tests) {
		if (test.first.find(prefix) != std::string::npos) {
			++to_run;
