#include "geometry/halfedge.h"

#include <iostream>
#include <vector>

static void dump_mesh(char const* label, Halfedge_Mesh const& mesh) {
	std::cout << label << ": V=" << mesh.vertices.size()
	          << " E=" << mesh.edges.size()
	          << " F=" << mesh.faces.size()
	          << " B=" << mesh.n_boundaries() << "\n";

	size_t vi = 0;
	for (auto v = mesh.vertices.begin(); v != mesh.vertices.end(); ++v, ++vi) {
		std::cout << "  v" << vi << " id=" << v->id << " pos=("
		          << v->position.x << "," << v->position.y << "," << v->position.z << ")\n";
	}

	size_t fi = 0;
	for (auto f = mesh.faces.begin(); f != mesh.faces.end(); ++f, ++fi) {
		std::cout << "  f" << fi << (f->boundary ? " boundary" : "") << ":";
		auto h = f->halfedge;
		do {
			std::cout << " " << h->vertex->position;
			h = h->next;
		} while (h != f->halfedge);
		std::cout << "\n";
	}
}

int main() {
	Halfedge_Mesh square = Halfedge_Mesh::from_indexed_faces({
		Vec3{-0.5f, 0.0f, -0.5f}, Vec3{-0.5f, 0.0f, 0.5f},
		Vec3{0.5f, 0.0f, -0.5f}, Vec3{0.5f, 0.0f, 0.5f}
	}, {
		{1, 3, 2, 0}
	});

	dump_mesh("square before", square);
	square.linear_subdivide();
	if (auto msg = square.validate()) {
		std::cout << "validate error: " << msg->second << "\n";
	}
	dump_mesh("square after linear", square);

	Halfedge_Mesh cc_square = Halfedge_Mesh::from_indexed_faces({
		Vec3{-1.0f, 1.0f, 0.0f}, Vec3{1.0f, 1.0f, 0.0f},
		Vec3{-1.0f, -1.0f, 0.0f}, Vec3{1.0f, -1.0f, 0.0f}
	}, {
		{2, 3, 1, 0}
	});

	cc_square.catmark_subdivide();
	if (auto msg = cc_square.validate()) {
		std::cout << "cc validate error: " << msg->second << "\n";
	}
	dump_mesh("square after catmark", cc_square);

	return 0;
}

